            if (!otherKey || otherKey === storyKey) return;
            try {
                tracker.linkIssues(storyKey, otherKey, 'Relates');
                console.log(storyKey + ' relates to ' + otherKey + ' (integration)');
            } catch (e) {
                console.warn('Failed to link integration ' + storyKey + ' <-> ' + otherKey + ':', e);
            }
        });
