            { tempId: 's1', type: 'Story', summary: 'Story one', parent: 'e1', description: 'outputs/d.md', blockedBy: ['b1'], integrates: ['s2'] },
            { tempId: 's2', type: 'Story', summary: 'Story two', parent: 'P-9' },
