function getContentType(filePath) {
    var ext = filePath.split('.').pop().toLowerCase();
    var types = {
        'pdf':  'application/pdf',
        'png':  'image/png',
        'jpg':  'image/jpeg',
        'jpeg': 'image/jpeg',
