 */
function finalizeIntakeTicket(ctx, results, params) {
    postFinalComment(ctx, results);
    addIntakeLabels(ctx);
    assignAndMoveToInProgress(ctx);
    removeWipLabel(ctx);
    postTokenUsage(ctx, params);
